/**
 * @method
 * @name img_LD_HALT_RSN_CD_onclick
 * @description img_LD_HALT_RSN_CD 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_LD_HALT_RSN_CD_onclick = async function() {
    try {
        scwin.fn_GetPar = scwin.getParRsnCd;
        scwin.fn_SetPar = scwin.setParRsnCd;
        const options = {
            id: "ULDSTF92007",
            title: "코드선택",
            type: "browserPopup",
            width: 515 + 5,
            height: 315 + 30,
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/listingcommon/ULDSTF92007.gfm", options);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF21300.img_LD_HALT_RSN_CD_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_1_onclick
 * @description 「조회」 클릭 이벤트
