scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF21300.xml", SCREN_PROCS_TP_CD_07); // 엑셀
        if (MaxTab_01.getSelectedTabIndex() === 1) {
            $c.data.downloadGridViewExcel(grd_List_1, {fileName: "현재 매매거래정지내역", type: "8"});
        } else if (MaxTab_01.getSelectedTabIndex() === 2) {
            $c.data.downloadGridViewExcel(grd_List_2, {fileName: "매매거래정지내역", type: "8"});
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21300.btn_Excel_onclick" });
    }
};

