///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    chb_Grp_All_1.setValue(1);
    chb_Grp_All_2.setValue(1);
    scwin.allCheck1();
    scwin.allCheck2();

    //  기간 from~ to  셋팅
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue($c.ut.cGetMinusDate2(vCurDate, 7)); // 일주일전 날짜
    edt_EDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)
    // dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    const sbmOptions = {
        id : "sbm_dts_dep",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_dep=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)
    const sbmOptions2 = {
        id : "sbm_dts_emp",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_emp=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        let comNm = txb_COM_NM_1.getValue();
        let secuGrpId = "";
        if (chb_Grp_St_1.getValue() === 'Y') secuGrpId += 'ST,DR,FS,IF,';
        if (chb_Grp_Mf_1.getValue() === 'Y') secuGrpId += 'MF,';
        if (chb_Grp_Sc_1.getValue() === 'Y') secuGrpId += 'SC,';
        if (chb_Grp_Rt_1.getValue() === 'Y') secuGrpId += 'RT,';
        if (chb_Grp_All_1.getValue() === 'Y') secuGrpId = '';
        // if (getObjectValue(chb_Grp_All_1) =='Y')        secuGrpId = 'ST,DR,FS,IF,MF,SC,RT';

        url += "?SCREN_ID=" + "ULDSTF21300.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listStockTradingSuspension&inputMessageId=LISTED_SEARCH_TRD_HALT_OUT";
        url += "&gubun=1";
        url += "&comNm=" + comNm.replace("&", "＆");
        url += "&secuGrpId=" + secuGrpId;
        url += "&kindCd=" + rdo_STKCERT_KIND_CD.getValue();
        const sbmOptions = {
            id : "sbm_dts_List_1",
            action : "/ListedSearch.do",
            ref : "",
            target : "dts_List_1=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        let comNm = txb_COM_NM_2.getValue();
        let secuGrpId = "";
        if (chb_Grp_St_2.getValue() === 'Y') secuGrpId += 'ST,DR,FS,IF,';
        if (chb_Grp_Mf_2.getValue() === 'Y') secuGrpId += 'MF,';
        if (chb_Grp_Sc_2.getValue() === 'Y') secuGrpId += 'SC,';
        if (chb_Grp_Rt_2.getValue() === 'Y') secuGrpId += 'RT,';
        if (chb_Grp_All_2.getValue() === 'Y') secuGrpId = '';
        // if (getObjectValue(chb_Grp_All_2) =='Y')        secuGrpId = 'ST,DR,FS,IF,MF,SC,RT';
        url += "?SCREN_ID=" + "ULDSTF21300.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listStockTradingSuspension&inputMessageId=LISTED_SEARCH_TRD_HALT_OUT";
        url += "&gubun=2";
        url += "&comNm=" + comNm.replace("&", "＆");
        url += "&secuGrpId=" + secuGrpId;
        url += "&startDate=" + edt_SDate.getValue();
        url += "&endDate=" + edt_EDate.getValue();
        url += "&depCd=" + cmb_TeamList.getValue();
        url += "&empNo=" + cmb_EmpList.getValue();
        url += "&listStatCd=" + rdo_LIST_STAT_CD.getValue();
        url += "&rsnCd=" + txb_LD_HALT_RSN_CD.getValue();
        url += "&kindCd=" + rdo_STKCERT_KIND_CD2.getValue();
        const sbmOptions = {
            id : "sbm_dts_List_2",
            action : "/ListedSearch.do",
            ref : "",
            target : "dts_List_2=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

