/**
 * @method
 * @name setParRsnCd
 * @description set Par Rsn Cd 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParRsnCd = function(arrPar) {
    txb_LD_HALT_RSN_CD.setValue((arrPar.length >= 1 ? arrPar[0] : ""));
    txb_LD_HALT_RSN_NM.setValue((arrPar.length >= 2 ? arrPar[1] : ""));
};

/**
 * @method
 * @name allCheck1
 * @description all Check1 처리
 * @returns {void}
 * @hidden N
 */
scwin.allCheck1 = function() {
    let checkArray = [chb_Grp_St_1, chb_Grp_Mf_1, chb_Grp_Sc_1, chb_Grp_Rt_1];
    if (chb_Grp_All_1.checked === true) {
        for (let i = 0; i < checkArray.length; i++) {
            checkArray[i].setValue(0);
        }
    }
};

